Here is the root cause:
The bug arises from improper wait queue management in snd_pcm_drain() for linked streams. The old code used `init_waitqueue_entry` (which does not clear `prev/next`) combined with `add_wait_queue` and a conditional `remove_wait_queue` that is skipped when the target substream (`to_check`) is concurrently unlinked from the group. This leaves the wait entry orphaned on the old sleep queue. On the next drain loop iteration, `add_wait_queue` adds the same entry to a new queue while it is still linked on the old one, corrupting both list structures. A subsequent `wake_up` misinterprets the corrupted list head as a function pointer (the spinlock at offset 0 of a `wait_queue_head_t`) and dereferences NULL, causing a kernel panic. The fix replaces the pattern with `init_wait_entry` (which clears `prev/next` and sets `autoremove_wake_function`), `prepare_to_wait`, and `finish_wait`; the latter safely handles both auto-removed and still-queued cases, preventing the double-listing corruption.

Here is the patch:
  */
 static int snd_pcm_drain(struct snd_pcm_substream *substream,
 			 struct file *file)
 {
 	struct snd_card *card;
 	struct snd_pcm_runtime *runtime;
 	struct snd_pcm_substream *s;
 	struct snd_pcm_group *group;
 	wait_queue_entry_t wait;
 	int result = 0;
 	int nonblock = 0;

 	card = substream->pcm->card;
 	runtime = substream->runtime;

 	if (runtime->state == SNDRV_PCM_STATE_OPEN)
 		return -EBADFD;

 	if (file) {
 		if (file->f_flags & O_NONBLOCK)
 			nonblock = 1;
 	} else if (substream->f_flags & O_NONBLOCK)
 		nonblock = 1;

 	snd_pcm_stream_lock_irq(substream);
 	/* resume pause */
 	if (runtime->state == SNDRV_PCM_STATE_PAUSED)
 		snd_pcm_pause(substream, false);

 	/* pre-start/stop - all running streams are changed to DRAINING state */
 	result = snd_pcm_action(&snd_pcm_action_drain_init, substream,
 				ACTION_ARG_IGNORE);
 	if (result < 0)
 		goto unlock;
 	/* in non-blocking, we don't wait in ioctl but let caller poll */
 	if (nonblock) {
 		result = -EAGAIN;
 		goto unlock;
 	}

 	for (;;) {
 		long tout;
 		struct snd_pcm_runtime *to_check;
 		unsigned int drain_rate;
 		snd_pcm_uframes_t drain_bufsz;
 		bool drain_no_period_wakeup;

 		if (signal_pending(current)) {
 			result = -ERESTARTSYS;
 			break;
 		}
 		/* find a substream to drain */
 		to_check = NULL;
 		group = snd_pcm_stream_group_ref(substream);
 		snd_pcm_group_for_each_entry(s, substream) {
 			if (s->stream != SNDRV_PCM_STREAM_PLAYBACK)
 				continue;
 			runtime = s->runtime;
 			if (runtime->state == SNDRV_PCM_STATE_DRAINING) {
 				to_check = runtime;
 				break;
 			}
 		}
 		snd_pcm_group_unref(group, substream);
 		if (!to_check)
 			break; /* all drained */
 		/*
 		 * Cache the runtime fields needed after unlock.
 		 * A concurrent close() on the linked stream may free
 		 * its runtime via snd_pcm_detach_substream() once we
 		 * release the stream lock below.
 		 */
 		drain_no_period_wakeup = to_check->no_period_wakeup;
 		drain_rate = to_check->rate;
 		drain_bufsz = to_check->buffer_size;
-		init_waitqueue_entry(&wait, current);
-		set_current_state(TASK_INTERRUPTIBLE);
-		add_wait_queue(&to_check->sleep, &wait);
+		init_wait_entry(&wait, 0);
+		prepare_to_wait(&to_check->sleep, &wait, TASK_INTERRUPTIBLE);
 		snd_pcm_stream_unlock_irq(substream);
 		if (drain_no_period_wakeup)
 			tout = MAX_SCHEDULE_TIMEOUT;
 		else {
 			tout = 100;
 			if (drain_rate) {
 				long t = drain_bufsz * 1100 / drain_rate;
 				tout = max(t, tout);
 			}
 			tout = msecs_to_jiffies(tout);
 		}
 		tout = schedule_timeout(tout);

 		snd_pcm_stream_lock_irq(substream);
 		group = snd_pcm_stream_group_ref(substream);
 		snd_pcm_group_for_each_entry(s, substream) {
 			if (s->runtime == to_check) {
-				remove_wait_queue(&to_check->sleep, &wait);
+				finish_wait(&to_check->sleep, &wait);
 				break;
 			}
 		}
 		snd_pcm_group_unref(group, substream);

 		if (card->shutdown) {
 			result = -ENODEV;
 			break;
 		}
 		if (tout == 0) {
 			if (substream->runtime->state == SNDRV_PCM_STATE_SUSPENDED)
 				result = -ESTRPIPE;
 			else {
 				dev_dbg(substream->pcm->card->dev,
 					"playback drain timeout (DMA or IRQ trouble?)\n");
 				snd_pcm_stop(substream, SNDRV_PCM_STATE_SETUP);
 				result = -EIO;
 			}
 			break;
 		}
 	}

  unlock:
 	snd_pcm_stream_unlock_irq(substream);

 	return result;
 }



